{
  "title": "夜探客栈",
  "scene": "你是一名初入江湖的少侠，听说附近的『迎春客栈』里藏有一份重要信件，涉及你师傅的一桩旧案。夜深人静，只有几盏油灯在微弱地亮着，风声透过破旧的窗纸，带来阵阵凉意。客栈的大门紧闭，但侧面的木窗似乎有些松动。而屋顶则显得更为安全，因为上面有你练习轻功时常见的瓦片。此时，你看到一位行色匆匆的黑衣人从后门进入，似乎并不注意周围。",
  "goal": "找到并取回重要信件",
  "clue": "侧面的木窗松动，黑衣人从后门进入",
  "choices": [
    {
      "id": "A",
      "text": "从正门直接闯入",
      "outcome": "你用力推开了大门，但因声音太大，惊动了客栈内的守卫，一番激战后，你虽然打赢了，但消耗了不少体力，也未能找到信件。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "跟随黑衣人进后门",
      "outcome": "你小心翼翼地跟在黑衣人身后，发现他并没有进入客栈的主厅，而是直奔马厩。你趁机进入了客栈，顺利找到了信件。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "轻功翻上屋顶",
      "outcome": "你轻盈地翻上了屋顶，发现屋顶的瓦片确实能帮助你悄无声息地进入客栈。你轻松找到了信件，并未引起任何人的注意。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
